def solve(g, mode='min'):
    H,W=len(g),len(g[0])
    cnt=Counter(x for r_ in g for x in r_)
    bg=max(cnt,key=lambda k:cnt[k])
    def ok(r,c): return 0<=r<H and 0<=c<W and g[r][c]==bg
    dist={}
    q=deque()
    mks=[(r,c) for r in range(H) for c in range(W) if g[r][c]==2]
    for s in mks: dist[s]=0; q.append(s)
    while q:
        r,c=q.popleft()
        for dr,dc in [(1,0),(-1,0),(0,1),(0,-1)]:
            nr,nc=r+dr,c+dc
            if ok(nr,nc) and (nr,nc) not in dist:
                dist[(nr,nc)]=dist[(r,c)]+1; q.append((nr,nc))
    tts=[(r,c) for r in range(H) for c in range(W) if g[r][c]==3]
    if not tts: return None
    tds={t:dist.get(t,9e9) for t in tts}
    tt=min(tds,key=tds.get)
    # backtrace from target to first marker
    cur=tt; path=[]
    while cur not in dist or True:
        path.append(cur); break
    parent=None
    cur=tt
    while dist[cur]>0 or True:
        # find predecessor with dist one less that is connected via bg
        pred=None
        for dr,dc in [(1,0),(-1,0),(0,1),(0,-1)]:
            nr,nc=cur[0]+dr,cur[1]+dc
            if (nr,nc) in dist and dist[(nr,nc)]==dist[cur]-1 and g[nr][nc]==bg:
                pred=(nr,nc);break
        else:
            # try passing through marker directly (stop when reaching a 2-neighbor)
            hit=False
            for dr,dc in [(1,0),(-1,0),(0,1),(0,-1)]:
                nr,nc=cur[0]+dr,cur[1]+dc
                if 0<=nr<H and 0<=nc<W and g[nr][nc]==2: hit=True; break
            if not hit: break
        cur=pred
    path.sort(); path=set(path)
    out=[r[:] for r in g]
    for r in range(H):
        for c in range(W):
            if (r,c) in path and g[r][c]!=3: out[r][c]=3
    return out

