    ok=lambda r,c: 0<=r<H and 0<=c<W and g[r][c]==bg
    # seeds: bg cells orthogonally adjacent to marker block
    seeds=[(r,c) for r,c in [(x+dr,y+dc) for x,y in mk for dr,dc in [(1,0),(-1,0),(0,1),(0,-1)]]
           if ok(r,c) and not (x,y) in set() ]
    dist={}
    q=deque(seeds); seeds=set(seeds)
    while q:
        r,c=q.popleft()
        for dr,dc in [(1,0),(-1,0),(0,1),(0,-1)]:
            nr,nc=r+dr,c+dc
            if ok(nr,nc) and (nr,nc) not in seeds and (nr,nc) not in dist:
                dist[(nr,nc)]=(r,c)+((r-c))+1 if False else dist.get((r,c),0)+1
                dist[(nr,nc)]=dist[(r,c)]+1
                q.append((nr,nc))
    dd={t:dist.get(t,9e9) for t in tr}
    tt=min(dd,key=dd.get) if any(d<9e9 for d in dd) else None
